const r = $input.first().json;
const dryRun = r.new_leads + r.new_mqls + r.booked_calls === 0;
const lines = [];
lines.push(`*Daily ops* — ${new Date(Date.now() - 86400000).toISOString().slice(0,10)}`);
lines.push(`• New leads: *${r.new_leads}*`);
lines.push(`• New MQLs: *${r.new_mqls}*`);
lines.push(`• Calls booked: *${r.booked_calls}*`);
lines.push(`• Top source: ${r.top_source || '—'}`);
lines.push(`• Claude spend: AED *${r.claude_aed}*${r.claude_aed > 100 ? ' ⚠️ over daily target' : ''}`);
if (dryRun) lines.push('_(quiet day — no movement)_');
return [{ json: { text: lines.join('\n') } }];
